class UniqueQueue {
  constructor() {
    this.queue = new Array();
  }
  push(value, attempts) {
    if (attempts < 1) {
      console.error("Triyng to enqueue item with attempts < 1");
      return;
    }
    this.remove(value);
    this.queue.push({ value, attempts });
  }
  remove(value) {
    this.queue = this.queue.filter((item) => item.value !== value);
  }
  iterationQueue() {
    const extractIteration = (prev, curr) => {
      prev.iteration.push(curr.value);
      if (curr.attempts > 1) {
        prev.queue.push(curr.value, curr.attempts - 1);
      }
      return prev;
    };
    const { queue, iteration } = this.queue.reduce(extractIteration, {
      queue: new UniqueQueue(),
      iteration: []
    });
    this.queue = queue.queue;
    return iteration;
  }
}

class ModalW1 extends obsidian.Modal {
  constructor(app) {
    super(app);
    this.messg = "";
    this.callbackFunc = null;
  }
  onOpen() {
    let { contentEl, titleEl } = this;
    titleEl.setText(APP_NAME);
    contentEl.createDiv({
      text: this.messg
    });
    contentEl.createEl("button", {
      cls: ["mod-cta"],
      text: isChineseDisplayLanguage() ? "\u53D6\u6D88" : "Cancel"
    }).addEventListener("click", async () => {
      this.close();
    });
    contentEl.createEl("button", {
      cls: ["mod-cta"],
      text: isChineseDisplayLanguage() ? "\u786E\u8BA4" : "Confirm"
    }).addEventListener("click", async () => {
      this.close();
      if (this.callbackFunc) {
        this.callbackFunc();
      }
    });
  }
  onClose() {
    let { contentEl } = this;
    contentEl.empty();
  }
}

